// A grow buffer with 5 bytes written: its allocated size is larger, and only the 5 bytes should reach Steam Cloud
var b = buffer_create(64, buffer_grow, 1);
buffer_write(b, buffer_u8, 1); buffer_write(b, buffer_u8, 2); buffer_write(b, buffer_u8, 3); buffer_write(b, buffer_u8, 4); buffer_write(b, buffer_u8, 5);
var ok = steam_remote_storage_file_write("gametest_write_default.bin", b);
buffer_delete(b);
return ok ? 1 : 0;

var n = steam_remote_storage_get_file_size("gametest_write_default.bin");
show_debug_message("gametest: cloud file size without a count: " + string(n));
return n;

// With an offset of 2 and no count, the bytes written after the offset: 3
var b = buffer_create(64, buffer_grow, 1);
repeat (5) buffer_write(b, buffer_u8, 7);
var ok = steam_remote_storage_file_write("gametest_write_offset.bin", b, 2);
buffer_delete(b);
return ok ? 1 : 0;

var n = steam_remote_storage_get_file_size("gametest_write_offset.bin");
show_debug_message("gametest: cloud file size with offset 2: " + string(n));
return n;

var a = steam_remote_storage_file_delete("gametest_write_default.bin");
var c = steam_remote_storage_file_delete("gametest_write_offset.bin");
return (a && c) ? 1 : 0;
